/**
 * In-memory data store for todos.
 * Structure: Map<id, todoObject>
 */
let todosStore = [];

/**
 * Helper function to generate a unique ID (using simple counter for determinism in tests)
 * @returns {string} A pseudo-unique ID
 */
const getNextId = () => `todo-${todosStore.length + 1}`;

/**
 * Retrieves all todo items, optionally filtering by completion status.
 * @param {boolean | null} [completed=null] Filter by completed status (true/false). Null retrieves all.
 * @returns {Array<object>} List of todos.
 */
const findAllTodos = (completed = null) => {
    if (completed === null) return [...todosStore];
    return todosStore.filter(todo => todo.completed === completed);
};

/**
 * Finds a single todo item by ID.
 * @param {string} id The ID of the todo to find.
 * @returns {object | undefined} The found todo object or undefined.
 */
const findTodoById = (id) => {
    return todosStore.find(todo => todo.id === id);
};

/**
 * Adds a new todo item to the store.
 * @param {string} title Title of the todo.
 * @param {boolean} [completed=false] Initial completion status.
 * @returns {object} The created todo object.
 */
const createTodo = (title, completed) => {
    const newTodo = {
        id: getNextId(),
        title: title,
        completed: completed === undefined ? false : !!completed,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
    };
    todosStore.push(newTodo);
    return newTodo;
};

/**
 * Updates an existing todo item by ID.
 * @param {string} id The ID of the todo to update.
 * @param {object} updates Object containing fields to update (e.g., {title: 'New Title', completed: true}).
 * @returns {object | null} The updated todo object, or null if not found.
 */
const updateTodo = (id, updates) => {
    const index = todosStore.findIndex(todo => todo.id === id);
    if (index === -1) return null;

    const existingTodo = todosStore[index];
    const updatedTodo = {
        ...existingTodo,
        ...updates,
        updatedAt: new Date().toISOString(), // Always update timestamp
    };

    // Ensure completed is always a boolean if provided in updates
    if (typeof updates.completed !== 'undefined') {
        updatedTodo.completed = !!updates.completed;
    }

    todosStore[index] = updatedTodo;
    return updatedTodo;
};

/**
 * Deletes a todo item by ID.
 * @param {string} id The ID of the todo to delete.
 * @returns {boolean} True if deletion was successful, false otherwise.
 */
const deleteTodo = (id) => {
    const initialLength = todosStore.length;
    todosStore = todosStore.filter(todo => todo.id !== id);
    return todosStore.length < initialLength;
};

module.exports = {
    findAllTodos,
    findTodoById,
    createTodo,
    updateTodo,
    deleteTodo,
};
