const todoService = require('./store');

/**
 * Controller for handling GET /todos and GET /todos/:id requests.
 * @param {object} req Express request object.
 * @param {object} res Express response object.
 */
const getTodos = (req, res) => {
    // Requirement 3: Support ?completed=true/false filter
    const completedFilterParam = req.query.completed;
    let filteredList;

    if (completedFilterParam === 'true') {
        filteredList = todoService.findAllTodos(true);
    } else if (completedFilterParam === 'false') {
        filteredList = todoService.findAllTodos(false);
    } else {
        // No filter or invalid filter, return all
        filteredList = todoService.findAllTodos(null);
    }

    res.status(200).json(filteredList);
};

/**
 * Controller for handling GET /todos/:id requests.
 * @param {object} req Express request object (expects ID in params.id).
 * @param {object} res Express response object.
 */
const getTodoById = (req, res) => {
    const id = req.params.id;
    const todo = todoService.findTodoById(id);

    if (!todo) {
        return res.status(404).json({ error: `Todo with ID ${id} not found.` });
    }

    res.status(200).json(todo);
};

/**
 * Controller for handling POST /todos requests (Create Todo).
 * @param {object} req Express request object (expects body JSON).
 * @param {object} res Express response object.
 */
const createTodo = (req, res) => {
    const { title, completed } = req.body;

    // Requirement 6 & 7: Input validation on all write endpoints
    if (!title || typeof title !== 'string' || title.length < 1 || title.length > 100) {
        return res.status(400).json({ error: "Validation Failed: Title is required, must be a string, and between 1 and 100 characters." });
    }

    // Default completed status if not provided or invalid type
    const finalCompleted = (typeof completed === 'boolean') ? completed : false;

    try {
        const newTodo = todoService.createTodo(title, finalCompleted);
        res.status(201).json(newTodo); // 201 Created
    } catch (error) {
        console.error("Error creating todo:", error);
        res.status(500).json({ error: "Internal Server Error while creating todo." });
    }
};

/**
 * Controller for handling PUT /todos/:id requests (Update Todo).
 * @param {object} req Express request object (expects ID in params, updates in body).
 * @param {object} res Express response object.
 */
const updateTodo = (req, res) => {
    const id = req.params.id;
    const updates = req.body;

    // 1. Check if the resource exists first
    if (!todoService.findTodoById(id)) {
        return res.status(404).json({ error: `Cannot update. Todo with ID ${id} not found.` });
    }

    // 2. Validate incoming updates
    const validatedUpdates = {};

    if (updates.title !== undefined) {
        if (typeof updates.title !== 'string' || updates.title.length < 1 || updates.title.length > 100) {
            return res.status(400).json({ error: "Validation Failed: Title must be a string between 1 and 100 characters." });
        }
        validatedUpdates.title = updates.title;
    }

    if (typeof updates.completed !== 'undefined') {
        // Ensure completed is passed as a boolean type in the request body
        if (typeof updates.completed !== 'boolean') {
             return res.status(400).json({ error: "Validation Failed: Completed status must be a boolean (true/false)." });
        }
        validatedUpdates.completed = updates.completed;
    }

    // If no valid fields were provided for update
    if (Object.keys(validatedUpdates).length === 0) {
         return res.status(400).json({ error: "Validation Failed: At least one field (title or completed) must be provided for update." });
    }

    try {
        const updatedTodo = todoService.updateTodo(id, validatedUpdates);
        // Since we already checked existence above, this should always pass if updates were valid
        if (!updatedTodo) return res.status(500).json({ error: "Failed to update record." });

        res.status(200).json(updatedTodo); // 200 OK
    } catch (error) {
        console.error("Error updating todo:", error);
        res.status(500).json({ error: "Internal Server Error while updating todo." });
    }
};

/**
 * Controller for handling DELETE /todos/:id requests.
 * @param {object} req Express request object (expects ID in params.id).
 * @param {object} res Express response object.
 */
const deleteTodo = (req, res) => {
    const id = req.params.id;

    // Check existence before attempting deletion
     if (!todoService.findTodoById(id)) {
        return res.status(404).json({ error: `Cannot delete. Todo with ID ${id} not found.` });
    }

    const wasDeleted = todoService.deleteTodo(id);

    if (wasDeleted) {
        // 204 No Content is standard for successful deletion when no body is returned
        res.status(204).send();
    } else {
        // Should theoretically not happen due to pre-check, but good practice
         res.status(500).json({ error: "Internal Server Error while deleting todo." });
    }
};

module.exports = {
    getTodos,
    getTodoById,
    createTodo,
    updateTodo,
    deleteTodo,
};
